snippet_css:
:root{
  --bg: #FDFBF7;
  --fg: #2F2F2F;
  --muted: #575757;
  --surface: #F4F2EC;
  --border: #C9C4B8;
  --accent: #1F4E9C;
  --accent-fg: #FFFFFF;
  --accent-grad: linear-gradient(180deg,#2E63B8,#1F4E9C);
  --radius: 6px;
  --radius-sm: 4px;
  --shadow: 4px 4px 0 rgba(47,47,47,.14);
  --btn-shadow: 3px 3px 0 rgba(31,78,156,.30);
  --art-bg: linear-gradient(#E4E7EE 1px,transparent 1px) 0 0/26px 26px,linear-gradient(90deg,#E4E7EE 1px,transparent 1px) 0 0/26px 26px,#FDFBF7;
  --media-bg: repeating-linear-gradient(0deg,#E7E4DB 0 1px,transparent 1px 22px),#FDFBF7;
  --cta-bg: linear-gradient(transparent 58%,#FFF36B 58% 92%,transparent 92%),#FDFBF7;
  --input-bg: #FFFFFF;
  --ok: #1F6B3B;
  --warn: #B3402F;
  --hl: #FFF36B;
  --font-hand: 'Caveat',cursive;
  --font-display: 'Architects Daughter','Noto Sans TC',cursive;
  --font-body: 'Patrick Hand','Noto Sans TC',cursive;
  --font-mono: 'Patrick Hand',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

